/** Error raised for invalid table input. */
export class TableError extends Error {
  /**
   * @param {string} code Stable machine-readable reason.
   * @param {string} message Human-readable detail.
   */
  constructor(code, message) {
    super(message);
    this.name = 'TableError';
    this.code = code;
  }
}

const WIDE_RANGES = [
  [0x1100, 0x115f],
  [0x2e80, 0x303e],
  [0x3041, 0x33ff],
  [0x3400, 0x4dbf],
  [0x4e00, 0x9fff],
  [0xa000, 0xa4cf],
  [0xac00, 0xd7a3],
  [0xf900, 0xfaff],
  [0xfe10, 0xfe19],
  [0xfe30, 0xfe6f],
  [0xff00, 0xff60],
  [0xffe0, 0xffe6],
  [0x1f300, 0x1f64f],
  [0x1f900, 0x1f9ff],
  [0x20000, 0x2fffd],
  [0x30000, 0x3fffd],
];

const ZERO_WIDTH_SET = new Set([0x200b, 0x200c, 0x200d, 0xfeff]);

/**
 * Column width of a single code point.
 *
 * @param {number} cp Unicode code point.
 * @returns {0|1|2} Column count for that code point.
 */
function codePointWidth(cp) {
  if (cp < 0x20 || cp === 0x7f) return 0;
  if (ZERO_WIDTH_SET.has(cp)) return 0;
  if (cp >= 0x300 && cp <= 0x36f) return 0;
  for (const [lo, hi] of WIDE_RANGES) {
    if (cp >= lo && cp <= hi) return 2;
  }
  return 1;
}

/**
 * Display width of a string in terminal columns.
 *
 * @param {string} text Text to measure.
 * @returns {number} Column count.
 */
export function stringWidth(text) {
  if (typeof text !== 'string') {
    throw new TableError('BAD_CELL', 'cell must be a string');
  }
  let width = 0;
  for (const ch of text) {
    width += codePointWidth(ch.codePointAt(0));
  }
  return width;
}

/**
 * Validate that width is a positive integer, throwing otherwise.
 *
 * @param {number} width Candidate width.
 * @returns {void}
 */
function checkWidth(width) {
  if (!Number.isInteger(width) || width < 1) {
    throw new TableError('BAD_WIDTH', 'width must be a positive integer');
  }
}

/**
 * Break a single overlong word into width-fitting chunks.
 *
 * @param {string} word Word with no internal spaces.
 * @param {number} width Column width.
 * @returns {string[]} Chunks, each fitting within width.
 */
function breakWord(word, width) {
  const chunks = [];
  let current = '';
  let currentWidth = 0;
  for (const ch of word) {
    const w = codePointWidth(ch.codePointAt(0));
    if (w > width) {
      throw new TableError('UNWRAPPABLE', 'character is wider than the column');
    }
    if (currentWidth + w > width) {
      chunks.push(current);
      current = ch;
      currentWidth = w;
    } else {
      current += ch;
      currentWidth += w;
    }
  }
  if (current !== '') chunks.push(current);
  return chunks;
}

/**
 * Greedily pack tokens into lines separated by single spaces.
 *
 * @param {string[]} tokens Words/chunks in order.
 * @param {number} width Column width.
 * @returns {string[]} Packed lines.
 */
function packTokens(tokens, width) {
  const lines = [];
  let curLine = '';
  let curWidth = 0;
  for (const token of tokens) {
    const tw = stringWidth(token);
    if (curLine === '') {
      curLine = token;
      curWidth = tw;
    } else if (curWidth + 1 + tw <= width) {
      curLine += ' ' + token;
      curWidth += 1 + tw;
    } else {
      lines.push(curLine);
      curLine = token;
      curWidth = tw;
    }
  }
  lines.push(curLine);
  return lines;
}

/**
 * Wrap a single newline-free piece of text.
 *
 * @param {string} piece Text without newlines.
 * @param {number} width Column width.
 * @returns {string[]} Lines the piece wraps to.
 */
function wrapPiece(piece, width) {
  const words = piece.split(/ +/).filter((w) => w.length > 0);
  if (words.length === 0) return [''];
  const tokens = [];
  for (const word of words) {
    if (stringWidth(word) <= width) {
      tokens.push(word);
    } else {
      for (const chunk of breakWord(word, width)) tokens.push(chunk);
    }
  }
  return packTokens(tokens, width);
}

/**
 * Wrap cell text to a column width.
 *
 * @param {string} text Cell text; explicit newlines start a new line.
 * @param {number} width Column width in display columns.
 * @returns {string[]} Wrapped lines, at least one.
 */
export function wrapCell(text, width) {
  if (typeof text !== 'string') {
    throw new TableError('BAD_CELL', 'cell must be a string');
  }
  checkWidth(width);
  const pieces = text.split('\n');
  const lines = [];
  for (const piece of pieces) {
    for (const line of wrapPiece(piece, width)) lines.push(line);
  }
  return lines;
}

const KNOWN_ALIGNS = new Set(['left', 'right', 'center']);

/**
 * Pad a single line to an exact display width.
 *
 * @param {string} text Line that already fits.
 * @param {number} width Target column width.
 * @param {'left'|'right'|'center'} [align] Alignment, left by default.
 * @returns {string} Padded line.
 */
export function padCell(text, width, align = 'left') {
  if (typeof text !== 'string') {
    throw new TableError('BAD_CELL', 'cell must be a string');
  }
  checkWidth(width);
  if (!KNOWN_ALIGNS.has(align)) {
    throw new TableError('BAD_ALIGN', `unknown alignment: ${align}`);
  }
  const textWidth = stringWidth(text);
  const diff = width - textWidth;
  if (diff < 0) {
    throw new TableError('CELL_TOO_WIDE', 'content is wider than the column');
  }
  if (align === 'left') return text + ' '.repeat(diff);
  if (align === 'right') return ' '.repeat(diff) + text;
  const leftPad = Math.floor(diff / 2);
  const rightPad = diff - leftPad;
  return ' '.repeat(leftPad) + text + ' '.repeat(rightPad);
}

/**
 * Render rows as a fixed-width table.
 *
 * @param {string[][]} rows Rows of cells.
 * @param {{widths: number[], align?: string[], header?: boolean}} options Layout options.
 * @returns {string} Table text without a trailing newline.
 */
export function formatTable(rows, options) {
  if (typeof options !== 'object' || options === null || Array.isArray(options)) {
    throw new TableError('BAD_OPTIONS', 'options must be an object');
  }
  const { widths, align: alignOption, header } = options;
  if (
    !Array.isArray(widths) ||
    widths.length === 0 ||
    !widths.every((w) => Number.isInteger(w) && w > 0)
  ) {
    throw new TableError('BAD_WIDTH', 'widths must be a non-empty array of positive integers');
  }
  const columns = widths.length;
  let align;
  if (alignOption !== undefined) {
    if (!Array.isArray(alignOption) || alignOption.length !== columns) {
      throw new TableError('BAD_ALIGN', `align must have ${columns} entries`);
    }
    for (const a of alignOption) {
      if (!KNOWN_ALIGNS.has(a)) {
        throw new TableError('BAD_ALIGN', `unknown alignment: ${a}`);
      }
    }
    align = alignOption;
  } else {
    align = Array.from({ length: columns }, () => 'left');
  }
  if (!Array.isArray(rows)) {
    throw new TableError('BAD_ROWS', 'rows must be an array');
  }
  for (let i = 0; i < rows.length; i += 1) {
    const row = rows[i];
    const count = Array.isArray(row) ? row.length : 0;
    if (count !== columns) {
      throw new TableError('BAD_ROW_LENGTH', `row ${i} has ${count} cells, expected ${columns}`);
    }
    for (let j = 0; j < columns; j += 1) {
      if (typeof row[j] !== 'string') {
        throw new TableError('BAD_CELL', `cell at row ${i}, column ${j} is not a string`);
      }
    }
  }
  if (rows.length === 0) return '';

  const outputLines = [];
  for (let i = 0; i < rows.length; i += 1) {
    const row = rows[i];
    const wrapped = row.map((cell, j) => wrapCell(cell, widths[j]));
    const height = Math.max(...wrapped.map((lines) => lines.length));
    for (let lineIdx = 0; lineIdx < height; lineIdx += 1) {
      const parts = wrapped.map((lines, j) => {
        const content = lineIdx < lines.length ? lines[lineIdx] : '';
        return padCell(content, widths[j], align[j]);
      });
      outputLines.push(parts.join(' | '));
    }
    if (header && i === 0) {
      const rule = widths.map((w) => '-'.repeat(w)).join('-+-');
      outputLines.push(rule);
    }
  }
  return outputLines.join('\n');
}
